// [WSCoop] Projectiles spawned by another projectile's hit have no owning ability component:
// orbit the caster instead (or the spawn point) rather than failing the whole spawn.
FVector OrbitCenter = ActorLocation;
if (BaseDesc.OwningAbilityComp != nullptr && BaseDesc.OwningAbilityComp.Owner != nullptr)
    OrbitCenter = BaseDesc.OwningAbilityComp.Owner.ActorLocation;
else if (BaseDesc.ActionEffectData.Instigator.Actor != nullptr)
    OrbitCenter = BaseDesc.ActionEffectData.Instigator.Actor.ActorLocation;
OrbitMovement.Init(BaseDesc.Orbit, ActorLocation, InitialVelocity, OrbitCenter);
